begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','food_quantity_policy_versions','versioned physical policies exist');
select has_table('public','food_price_purchase_terms','explicit sale terms exist');
select has_function('public','save_food_quantity_policy_draft',array['uuid','integer','jsonb','uuid'],'policy save is an authorized RPC');
select has_function('public','publish_food_quantity_policy',array['uuid','text','uuid','integer'],'policy publication is an authorized RPC');
select has_function('public','save_price_book_draft_v2',array['uuid','integer','date','date','jsonb','uuid'],'quote and terms save atomically');
insert into auth.users(id,email,raw_app_meta_data) values ('a1000000-0000-4000-8000-000000000001','physical-admin@example.test','{"role":"admin"}'),('a1000000-0000-4000-8000-000000000002','physical-reader@example.test','{}');
insert into public.foods(id,code,name_vi,base_dimension,base_unit_id) select 'a2000000-0000-4000-8000-000000000001','fish_portion_test','Cá phần thử','mass',id from public.units where code='g';
insert into public.food_fact_versions(id,food_id,version_number,category_id,edible_fraction,provenance,created_by) select 'a3000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001',1,id,1,'Synthetic test fact','a1000000-0000-4000-8000-000000000001' from public.food_categories where code='fish';
insert into public.food_fact_unit_conversions(food_fact_version_id,unit_id,base_quantity_per_unit,gross_grams_per_unit,display_step,provenance) select 'a3000000-0000-4000-8000-000000000001',id,1,1,5,'Synthetic gram identity' from public.units where code='g';
insert into public.food_fact_allergen_assessments(food_fact_version_id,allergen_id,assessment,provenance) select 'a3000000-0000-4000-8000-000000000001',id,case when code='fish' then 'contains'::public.allergen_assessment_status else 'absent'::public.allergen_assessment_status end,'Synthetic test assessment' from public.allergens;
insert into public.food_fact_nutrients(food_fact_version_id,nutrient_id,amount_per_100g,provenance) select 'a3000000-0000-4000-8000-000000000001',id,0,'Synthetic test nutrient' from public.nutrients;
select public.publish_food_fact_version('a3000000-0000-4000-8000-000000000001',repeat('a',64),'a1000000-0000-4000-8000-000000000001',1);
create temp table definitions as select jsonb_build_object('foodId','a2000000-0000-4000-8000-000000000001','foodFactVersionId','a3000000-0000-4000-8000-000000000001','versionNumber',1,'baseUnitId',id,'baseDimension','mass','foodForm','portionable_mass','stepBaseQuantity','1','rounding','half_up','provenance','Synthetic reviewed cut portions') as value from public.units where code='g';
select throws_ok($$select public.save_food_quantity_policy_draft('a4000000-0000-4000-8000-000000000001',1,(select value from definitions),'a1000000-0000-4000-8000-000000000002')$$,'42501','ADMIN_REQUIRED','ordinary user cannot author policies');
select lives_ok($$select public.save_food_quantity_policy_draft('a4000000-0000-4000-8000-000000000001',1,(select value from definitions),'a1000000-0000-4000-8000-000000000001')$$,'reviewed policy saves');
set local role authenticated;
select is((select count(*)::integer from public.food_quantity_policy_versions),0,'draft policies are not visible to authenticated readers');
select throws_ok($$insert into public.food_quantity_policy_versions(id) values(gen_random_uuid())$$,'42501',null,'authenticated has no policy write grant');
reset role;
select lives_ok($$select public.publish_food_quantity_policy('a4000000-0000-4000-8000-000000000001',repeat('b',64),'a1000000-0000-4000-8000-000000000001',1)$$,'policy publishes against exact fact');
select throws_ok($$update public.food_quantity_policy_versions set step_base_quantity=5 where id='a4000000-0000-4000-8000-000000000001'$$,'23514',null,'published policy immutable even to trusted SQL');
select throws_ok($$delete from public.food_quantity_policy_versions where id='a4000000-0000-4000-8000-000000000001'$$,'23514',null,'published policy cannot be deleted');
select lives_ok($$select public.save_food_quantity_policy_draft('a4000000-0000-4000-8000-000000000002',1,(select value||'{"versionNumber":2,"foodForm":"whole_piece","stepBaseQuantity":"200","rounding":"ceil"}'::jsonb from definitions),'a1000000-0000-4000-8000-000000000001')$$,'whole piece may remain draft pending conversion');
select throws_ok($$select public.publish_food_quantity_policy('a4000000-0000-4000-8000-000000000002',repeat('c',64),'a1000000-0000-4000-8000-000000000001',1)$$,'23514','INCOMPLETE_QUANTITY_POLICY','whole piece without measured count conversion is not publishable');
insert into public.price_books(id,region_id,version_number,effective_from,created_by) select 'a5000000-0000-4000-8000-000000000001',id,991,'2026-10-01','a1000000-0000-4000-8000-000000000001' from public.price_regions where code='vn_baseline';
create temp table prices as select jsonb_build_array(jsonb_build_object('food_id','a2000000-0000-4000-8000-000000000001','food_fact_version_id','a3000000-0000-4000-8000-000000000001','package_quantity','1000','package_unit_id',id,'package_base_quantity','1000','base_unit_id',id,'base_dimension','mass','package_price_vnd',100000,'purchase_increment','1','observed_at','2026-10-01','source_reference','Synthetic quote','purchase_rule',jsonb_build_object('mode','loose_mass','saleStepBaseQuantity','50'),'purchase_provenance','Synthetic supplier accepts 50g increments')) as value from public.units where code='g';
select throws_ok($$select public.save_price_book_draft_v2('a5000000-0000-4000-8000-000000000001',1,'2026-10-01',null,null,'a1000000-0000-4000-8000-000000000001')$$,'22023','PRICE_ROWS_REQUIRED','null price rows cannot clear an authored draft');
select throws_ok($$select public.save_price_book_draft_v2('a5000000-0000-4000-8000-000000000001',1,'2026-10-01',null,(select value||value from prices),'a1000000-0000-4000-8000-000000000001')$$,'23505',null,'duplicate food prices rejected atomically');
select is((select revision from public.price_books where id='a5000000-0000-4000-8000-000000000001'),1,'failed save leaves revision unchanged');
select lives_ok($$select public.save_price_book_draft_v2('a5000000-0000-4000-8000-000000000001',1,'2026-10-01',null,(select value from prices),'a1000000-0000-4000-8000-000000000001')$$,'v2 quote and terms save atomically');
select is((select count(*)::integer from public.food_price_purchase_terms),1,'explicit terms accompany each price');
select throws_ok($$update public.food_price_purchase_terms set sale_step_base_quantity=null$$,'23514',null,'required loose step cannot be omitted');
select throws_ok($$update public.price_books set purchase_contract_version=null where id='a5000000-0000-4000-8000-000000000001'$$,'23514','PURCHASE_CONTRACT_IMMUTABLE','declared purchasing version cannot be downgraded');
select throws_ok($$select public.save_price_book_draft_atomic('a5000000-0000-4000-8000-000000000001',2,'2026-10-01',null,(select value from prices),'a1000000-0000-4000-8000-000000000001')$$,'22023','PURCHASE_TERMS_REQUIRES_V2','legacy save cannot drop v2 author data');
select lives_ok($$select public.publish_price_book('a5000000-0000-4000-8000-000000000001',repeat('d',64),'a1000000-0000-4000-8000-000000000001',2)$$,'explicit v2 price book publishes');
select ok((select content_hash ~ '^[a-f0-9]{64}$' from public.food_price_purchase_terms),'published terms have a deterministic hash');
select throws_ok($$update public.food_price_purchase_terms set sale_step_base_quantity=100$$,'23514',null,'published sale terms immutable');
select throws_ok($$delete from public.food_price_purchase_terms$$,'23514',null,'published sale terms cannot be deleted');
set local role authenticated;
select is((select count(*)::integer from public.food_quantity_policy_versions),1,'authenticated can read published policies only');
select is((select count(*)::integer from public.food_price_purchase_terms),1,'authenticated can read published terms only');
select ok(not has_function_privilege('authenticated','public.save_food_quantity_policy_draft(uuid,integer,jsonb,uuid)','EXECUTE'),'policy mutation remains service-role only');
select ok(not has_function_privilege('anon','public.publish_food_quantity_policy(uuid,text,uuid,integer)','EXECUTE'),'anon cannot publish policies');
reset role;
select * from finish();
rollback;
